          const marca = capanga.effects.find(e => e.statuses.has('${S}-agarrado'))?.getFlag('${S}', 'agarrao')?.apertoDeFerro === true;
          // Recusados, os dois voltam na hora. Sem a recusa, o tiro abre a janela de defesa da Atiradora, que não tem
