            for (const efeito of ator.effects.filter(e => ['${S}-agarrado', '${S}-agarrando'].some(s => e.statuses.has(s)))) await efeito.delete().catch(() => {});
            if (ator.statuses.has('prone')) await ator.toggleStatusEffect('prone', { active: false });
